"""`aef init` — scaffold a brand-new agent directory from scratch, as
opposed to `aef adopt`, which retrofits an existing repo's current code.
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from pathlib import Path

# agent_name becomes both a filesystem path component (base_dir/agents/<name>)
# and is interpolated unescaped into generated Python source (_GRAPH_TEMPLATE's
# `id="{agent_name}"`) and YAML (_render_config). An unvalidated agent_name
# was a real, confirmed path-traversal bug: "../../evil" wrote files two
# directories above the intended agents/ tree, and an absolute path like
# "/etc/evil" discarded base_dir entirely (pathlib's `/` operator silently
# drops everything to the left of an absolute right-hand component) — see
# docs/adr/0029. A valid Python identifier is also what's actually needed
# here regardless of the security angle: the directory becomes an importable
# package (agents.<agent_name>), so an identifier is the correct constraint,
# not just a safe one.
_VALID_AGENT_NAME_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")


class InvalidAgentNameError(ValueError):
    pass


_GRAPH_TEMPLATE = '''"""Starter graph for the "{agent_name}" agent, generated by `aef init`."""

from __future__ import annotations

from aef.kernel import END, Context, Graph, Node, Route, Services
from aef.state import AEFState, Plan, Provenance, StateDelta


def hello_node(
    state: AEFState, ctx: Context, services: Services
) -> tuple[StateDelta, Route]:
    # Setting the plan status is not decoration. `Outcome.passed` requires
    # `plan_status == "done"`, and G2 skips any scenario whose incumbent did
    # not pass — so a graph that never sets a plan produces a corpus G2
    # cannot reject anything against, and reports "every previously-passing
    # one still passes" over scenarios where none ever passed (ADR 0075).
    # Provenance is what `aef trace` replays and what `aef eval` costs. The
    # kernel never appends it — it arrives only from a StateDelta — so a
    # graph that emits none replays empty and scores cost_tokens=0, which
    # reads as a broken tool rather than an agent that reported nothing.
    return (
        StateDelta(
            plan=Plan(goal=state.objective, status="done"),
            working_memory={{"greeted": True}},
            provenance=[
                Provenance(
                    node_id=ctx.node_id,
                    graph_version=ctx.graph_version,
                    ts=ctx.now,
                    trace_id=ctx.trace_id,
                    token_cost=0,
                )
            ],
        ),
        END,
    )


def build_graph() -> Graph:
    node = Node(id="hello", version="0.1.0", fn=hello_node, deterministic=True)
    return Graph(
        id="{agent_name}",
        version="0.1.0",
        nodes={{"hello": node}},
        edges=[],
        entry_node="hello",
    )
'''


def _render_config(agent_name: str) -> str:
    return f"""extends: _base

model_provider:
  impl: claude_code  # the coding agent's own login, no API key; or codex / anthropic
  model: claude-opus-5-5  # a real current ID; claude-fable-5-1 for the hardest long-horizon work
  fallback: []
  # effort: high  # optional, claude_code/anthropic; unset = model default (5.5: medium)

memory:
  impl: in_memory

evaluator:
  suites: []

tools:
  allow: []

policies:
  require_hitl_above_risk: 0.0
  forbid: []

objectives: "TODO: describe {agent_name}'s objective."

evolution:
  enabled: false
"""


@dataclass(frozen=True)
class InitResult:
    agent_name: str
    agent_dir: Path
    written_files: list[Path] = field(default_factory=list)
    skipped_files: list[Path] = field(default_factory=list)


def run_init(agent_name: str, base_dir: Path) -> InitResult:
    if not _VALID_AGENT_NAME_RE.match(agent_name):
        raise InvalidAgentNameError(
            f"agent_name must be a valid Python identifier (letters, digits, "
            f"underscores, not starting with a digit) — got {agent_name!r}"
        )

    agent_dir = base_dir.resolve() / "agents" / agent_name
    agent_dir.mkdir(parents=True, exist_ok=True)
    written: list[Path] = []
    skipped: list[Path] = []

    def _write_if_absent(path: Path, content: str) -> None:
        if path.exists():
            skipped.append(path)
            return
        path.write_text(content)
        written.append(path)

    _write_if_absent(agent_dir / "__init__.py", "")
    _write_if_absent(agent_dir / "aef.yaml", _render_config(agent_name))
    _write_if_absent(agent_dir / "graph.py", _GRAPH_TEMPLATE.format(agent_name=agent_name))

    return InitResult(
        agent_name=agent_name, agent_dir=agent_dir, written_files=written, skipped_files=skipped
    )
